(7317863, 1141992, 23484, '<td valign="top">Very neat composition.</td>', 'Very neat composition.', '2015-02-17 07:28:45.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7317864, 1141540, 23484, '<td valign="top">What a great catch. Nice job.</td>', 'What a great catch. Nice job.', '2015-02-17 07:29:01.000000', NULL, 1),
(7317871, 1141404, 114285, '<td valign="top">How can you not like this one.</td>', 'How can you not like this one.', '2015-02-17 09:29:46.000000', NULL, 1),
(7317873, 1141861, 114285, '<td valign="top">I would of cropped a quarter of the top off, to bring more attention to the workmen, good find though!</td>', 'I would of cropped a quarter of the top off, to bring more attention to the workmen, good find though!', '2015-02-17 09:32:26.000000', NULL, 1),
(7317876, 1142009, 114285, '<td valign="top">I really would love to know if this is a candid or not. Why do they all have umbrellas on a sunny day, I guess to keep the sun from beating down on their fare skin. The added clouds are a bonus...very toy storyish. <br/> <br/> <br/>This is one of the few I really like, and I mean few, truly!<br/> <br/>I''m sure it will be in the top five.</td>', 'I really would love to know if this is a candid or not. Why do they all have umbrellas on a sunny day, I guess to keep the sun from beating down on their fare skin. The added clouds are a bonus...very toy storyish.   This is one of the few I really like, and I mean few, truly! I''m sure it will be in the top five.', '2015-02-17 09:37:22.000000', NULL, 1),
(7317888, 1141969, 12611, '<td valign="top">I like the processing. I am feeling this shot as a dreamy, antique feeling ethereal offering- that being said, the details that should have been attended to include the power lines, the high tight crop, and the sliver of white at the bottom left.</td>', 'I like the processing. I am feeling this shot as a dreamy, antique feeling ethereal offering- that being said, the details that should have been attended to include the power lines, the high tight crop, and the sliver of white at the bottom left.', '2015-02-17 10:25:58.000000', NULL, 1),
(7317889, 1141716, 12611, '<td valign="top">So beautiful, dark and chaotic. Very nice detail, and although I am a fan of the combination of green and purple, perhaps a black and white or some monotone would have served you better.</td>', 'So beautiful, dark and chaotic. Very nice detail, and although I am a fan of the combination of green and purple, perhaps a black and white or some monotone would have served you better.', '2015-02-17 10:27:35.000000', NULL, 1),
(7317890, 1141399, 12611, '<td valign="top">The bird detail, the cross, and the solar flare are nice details. The golden tide is excellent as well, and where this falls short, is the inclusion of purple. the blue and purple combination doesn''t work so well.</td>', 'The bird detail, the cross, and the solar flare are nice details. The golden tide is excellent as well, and where this falls short, is the inclusion of purple. the blue and purple combination doesn''t work so well.', '2015-02-17 10:29:33.000000', NULL, 1),
(7317892, 1141791, 12611, '<td valign="top">You have gotten your Fibonacci on quite well here. There is an upside down Escher feel, and I feel the malevolence of abstract dragons and primordial aggressive nautilus creatures, however, the window in the top right brisk appears unplanned, and hurts the illusion a bit.</td>', 'You have gotten your Fibonacci on quite well here. There is an upside down Escher feel, and I feel the malevolence of abstract dragons and primordial aggressive nautilus creatures, however, the window in the top right brisk appears unplanned, and hurts the illusion a bit.', '2015-02-17 10:38:07.000000', NULL, 1),
(7317917, 1140964, 61234, '<td valign="top">Love this! Will be in the top 3 for sure!~ 10</td>', 'Love this! Will be in the top 3 for sure!~ 10', '2015-02-17 11:31:45.000000', NULL, 1),
(7317918, 1141438, 61234, '<td valign="top">Fabulous!</td>', 'Fabulous!', '2015-02-17 11:31:55.000000', NULL, 1),
(7317919, 1141879, 61234, '<td valign="top">Excellent!</td>', 'Excellent!', '2015-02-17 11:32:06.000000', NULL, 1),
