(7318059, 1141561, 23484, '<td valign="top">The blast from the sun.</td>', 'The blast from the sun.', '2015-02-17 18:59:37.000000', NULL, 1),
(7318069, 1141206, 114285, '<td valign="top">Unique perspective, well done!</td>', 'Unique perspective, well done!', '2015-02-17 19:43:09.000000', NULL, 1),
(7318070, 1142094, 114285, '<td valign="top">Reminds me of the 50''s somehow.</td>', 'Reminds me of the 50''s somehow.', '2015-02-17 19:43:36.000000', NULL, 1),
(7318075, 1140964, 114285, '<td valign="top">Looks a little cartoonish, great scene though!</td>', 'Looks a little cartoonish, great scene though!', '2015-02-17 20:26:43.000000', NULL, 1),
(7318083, 1141540, 12611, '<td valign="top">It is clear and contrasted for sure, and the expression on the girl, coupled with the odd moves of the person in the foreground, seem to work when wrapped up in the title. Somehow it does not seem "candid enough" it looks too, staged, almost as if you could never be that close to the action, that much in the scene for the subjects not to notice, or perhaps the genious of the shot is that they don''t, because you are dancing right along...</td>', 'It is clear and contrasted for sure, and the expression on the girl, coupled with the odd moves of the person in the foreground, seem to work when wrapped up in the title. Somehow it does not seem "candid enough" it looks too, staged, almost as if you could never be that close to the action, that much in the scene for the subjects not to notice, or perhaps the genious of the shot is that they don''t, because you are dancing right along...', '2015-02-17 21:37:45.000000', NULL, 1),
(7318084, 1141854, 12611, '<td valign="top">great vintage feel.</td>', 'great vintage feel.', '2015-02-17 21:38:29.000000', NULL, 1),
(7318086, 1141371, 12611, '<td valign="top">When the postcard announcing Judgement Day is sent, this image, with its vivid yellow oranges and midnight blacks,  will be the picture on it, and I won''t RSVP...</td>', 'When the postcard announcing Judgement Day is sent, this image, with its vivid yellow oranges and midnight blacks,  will be the picture on it, and I won''t RSVP...', '2015-02-17 21:40:16.000000', NULL, 1),
(7318088, 1141055, 12611, '<td valign="top">I get the clever starry night concept, but I immediately conjure up Van Gogh, and that was swirly, vivid, and oversaturated, an acid trip of twisted sky pleasure. This is a grainy, pointillism influenced underside of an overpass. It has value for its realist-"art hedged in non-art" ways-but the title sets it up for confusion, setting the bar impossibly high for the merits of the shot- unable to rise all the way to the lofty comparison.</td>', 'I get the clever starry night concept, but I immediately conjure up Van Gogh, and that was swirly, vivid, and oversaturated, an acid trip of twisted sky pleasure. This is a grainy, pointillism influenced underside of an overpass. It has value for its realist-"art hedged in non-art" ways-but the title sets it up for confusion, setting the bar impossibly high for the merits of the shot- unable to rise all the way to the lofty comparison.', '2015-02-17 21:47:44.000000', NULL, 1),
(7318090, 1140972, 12611, '<td valign="top">Beautiful light. and to think they are all one organism, perhaps, makes it creepy.</td>', 'Beautiful light. and to think they are all one organism, perhaps, makes it creepy.', '2015-02-17 21:48:55.000000', NULL, 1),
(7318091, 1142019, 30049, '<td valign="top">Kind of wish you''d cropped the top 10% or so of this. Otherwise, I still like it.  Well seen and captured.</td>', 'Kind of wish you''d cropped the top 10% or so of this. Otherwise, I still like it.  Well seen and captured.', '2015-02-17 21:49:15.000000', NULL, 1),
(7318093, 1140964, 30049, '<td valign="top">Stunning!!!</td>', 'Stunning!!!', '2015-02-17 21:56:01.000000', NULL, 1),
