(7318149, 1142001, 138630, '<td valign="top">Why does this feel so much like a Magritte to me?  Perfect for an art challenge.  I love it.</td>', 'Why does this feel so much like a Magritte to me?  Perfect for an art challenge.  I love it.', '2015-02-18 00:21:20.000000', NULL, 1),
(7318151, 1141385, 138630, '<td valign="top">Love the balance of the composition and the absurdity of the elements.  Well processed, too.  Nicely "arty".</td>', 'Love the balance of the composition and the absurdity of the elements.  Well processed, too.  Nicely "arty".', '2015-02-18 00:22:44.000000', NULL, 1),
(7318154, 1140962, 138630, '<td valign="top">Top pick for me.  Still struggling to express why.  I see life and death; youth and age; light and shadow; negative and positive; now and then; yesterday, today and tomorrow.  Great tones.</td>', 'Top pick for me.  Still struggling to express why.  I see life and death; youth and age; light and shadow; negative and positive; now and then; yesterday, today and tomorrow.  Great tones.', '2015-02-18 00:38:11.000000', NULL, 1),
(7318155, 1140972, 138630, '<td valign="top">Very different from my other top picks but I love this.  Great depth, crispness, tonal range, silence, serenity.</td>', 'Very different from my other top picks but I love this.  Great depth, crispness, tonal range, silence, serenity.', '2015-02-18 00:39:12.000000', NULL, 1),
(7318157, 1141802, 138630, '<td valign="top">Joy, pure and unadulterated and unbridled.  This is about exploration and discovery, about living in the moment.</td>', 'Joy, pure and unadulterated and unbridled.  This is about exploration and discovery, about living in the moment.', '2015-02-18 00:41:03.000000', NULL, 1),
(7318165, 1141104, 138630, '<td valign="top">Geometry.  Punctuated by the human form.  Love the colors and balance here.</td>', 'Geometry.  Punctuated by the human form.  Love the colors and balance here.', '2015-02-18 01:17:14.000000', NULL, 1),
(7318166, 1142101, 138630, '<td valign="top">Cold.  And windy.  And did I say cold?  I''m shivering.  Delightfully.</td>', 'Cold.  And windy.  And did I say cold?  I''m shivering.  Delightfully.', '2015-02-18 01:17:49.000000', NULL, 1),
(7318168, 1142019, 138630, '<td valign="top">I love the tones and textures here.  I like the way this one shimmers and shifts and keeps surprising me.</td>', 'I love the tones and textures here.  I like the way this one shimmers and shifts and keeps surprising me.', '2015-02-18 01:27:39.000000', NULL, 1),
