(7318313, 1141947, 12253, '<td valign="top">Commenting only: I like the high key here...though it might be a bit too high since their shirts disappear into the background.  The woman is thoroughly convincing here per the title.  The man not as much...he doesn''t seem as "into it".</td>', 'Commenting only: I like the high key here...though it might be a bit too high since their shirts disappear into the background.  The woman is thoroughly convincing here per the title.  The man not as much...he doesn''t seem as "into it".', '2015-02-18 12:20:08.000000', NULL, 1),
(7318314, 1142037, 12253, '<td valign="top">Commenting only: I love the shadow work and leading lines here.  I like the inclusion of the feet, but I think it''s a bit "too" cutoff.</td>', 'Commenting only: I love the shadow work and leading lines here.  I like the inclusion of the feet, but I think it''s a bit "too" cutoff.', '2015-02-18 12:20:58.000000', NULL, 1),
(7318319, 1141013, 12253, '<td valign="top">Commenting only: I''m having a bit of trouble connecting the title: where''s the bridge?  Or perhaps a metaphor I''m not getting from the shot.  A bit of intrigue is added to the shot with the man...though he''s not very salient here.  I like the depth of the photo, though the BG could use a bit more contrast IMHO.</td>', 'Commenting only: I''m having a bit of trouble connecting the title: where''s the bridge?  Or perhaps a metaphor I''m not getting from the shot.  A bit of intrigue is added to the shot with the man...though he''s not very salient here.  I like the depth of the photo, though the BG could use a bit more contrast IMHO.', '2015-02-18 12:31:11.000000', NULL, 1),
(7318322, 1141012, 63218, '<td valign="top">I agree. In the dictionary defining Impressionist Photography, this would be the illustration. It also defines the kind of spontaneous action that is the result of the camera finally becoming a part of the photographer''s brain. Well done.</td>', 'I agree. In the dictionary defining Impressionist Photography, this would be the illustration. It also defines the kind of spontaneous action that is the result of the camera finally becoming a part of the photographer''s brain. Well done.', '2015-02-18 12:32:35.000000', NULL, 1),
(7318323, 1141608, 12253, '<td valign="top">Commenting only: Lovely painted look.</td>', 'Commenting only: Lovely painted look.', '2015-02-18 12:33:34.000000', NULL, 1),
(7318359, 1141095, 23484, '<td valign="top">A precise moment in time.</td>', 'A precise moment in time.', '2015-02-18 14:16:16.000000', NULL, 1),
(7318360, 1141480, 23484, '<td valign="top">Love the starkness.</td>', 'Love the starkness.', '2015-02-18 14:16:47.000000', NULL, 1),
