(7319334, 1141385, 63218, '<td valign="top">I like the whimsy in this. And the grain. And the composition. And the textures. Thank you.</td>', 'I like the whimsy in this. And the grain. And the composition. And the textures. Thank you.', '2015-02-21 15:00:15.000000', NULL, 1),
(7319335, 1141784, 63218, '<td valign="top">An abstract! I love abstracts! This one puts me in mind of lilies, if they only came in crimson. It''d be fun to print this on canvas &amp; hang it on a wall painted the same shades of white.</td>', 'An abstract! I love abstracts! This one puts me in mind of lilies, if they only came in crimson. It''d be fun to print this on canvas & hang it on a wall painted the same shades of white.', '2015-02-21 15:05:24.000000', NULL, 1),
(7319336, 1141600, 63218, '<td valign="top">ooo yeah! this is gorgeous. as if trees were a giant form of ornamental grass. Spicy food for the imagination.</td>', 'ooo yeah! this is gorgeous. as if trees were a giant form of ornamental grass. Spicy food for the imagination.', '2015-02-21 15:08:36.000000', NULL, 1),
