INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7319602, 1141102, 96751, '<td valign="top">This time of day always makes me melancholic</td>', 'This time of day always makes me melancholic', '2015-02-21 20:03:30.000000', NULL, 1),
(7319603, 1141480, 96751, '<td valign="top">Glorious.  Makes my eyes dance a bit, but I like the shimmy</td>', 'Glorious.  Makes my eyes dance a bit, but I like the shimmy', '2015-02-21 20:03:58.000000', NULL, 1),
(7319604, 1141023, 96751, '<td valign="top">Not a oft-viewed angle</td>', 'Not a oft-viewed angle', '2015-02-21 20:04:14.000000', NULL, 1),
(7319605, 1141798, 96751, '<td valign="top">Somewhere between repulsion and fascination</td>', 'Somewhere between repulsion and fascination', '2015-02-21 20:04:40.000000', NULL, 1),
(7319607, 1140973, 96751, '<td valign="top">And a lovely shard at that</td>', 'And a lovely shard at that', '2015-02-21 20:05:16.000000', NULL, 1),
(7319608, 1142037, 96751, '<td valign="top">I would have taken this picture, too :)</td>', 'I would have taken this picture, too :)', '2015-02-21 20:06:08.000000', NULL, 1),
(7319609, 1142001, 96751, '<td valign="top">I think this is my favorite of the challenge.  I want to run with her</td>', 'I think this is my favorite of the challenge.  I want to run with her', '2015-02-21 20:06:43.000000', NULL, 1),
(7319611, 1142001, 170018, '<td valign="top">Mark, this is awesome! Your photo evokes so many emotions, colors and softness add to that! This is my favorite. 10</td>', 'Mark, this is awesome! Your photo evokes so many emotions, colors and softness add to that! This is my favorite. 10', '2015-02-21 20:11:24.000000', NULL, 1),
(7319612, 1141985, 138630, '<td valign="top">I''ve felt like this.  Many times.  Haunting.</td>', 'I''ve felt like this.  Many times.  Haunting.', '2015-02-21 20:14:24.000000', NULL, 1),
(7319614, 1142019, 103142, '<td valign="top">I like the idea, and it''s really close, but doesn''t quite make it. There''s no curiosity or emotions that I''m finding. A tad because of the rain -- adds a bit of melancholy. But I just think there could be more to it to hit the "art" stage. Something that draws you in over and over again.</td>', 'I like the idea, and it''s really close, but doesn''t quite make it. There''s no curiosity or emotions that I''m finding. A tad because of the rain -- adds a bit of melancholy. But I just think there could be more to it to hit the "art" stage. Something that draws you in over and over again.', '2015-02-21 20:17:46.000000', NULL, 1),
(7319615, 1142081, 103142, '<td valign="top">Not crazy about the bottle. Yet without the bottle, I think I would have liked it a lot. Seems too contrived this way.</td>', 'Not crazy about the bottle. Yet without the bottle, I think I would have liked it a lot. Seems too contrived this way.', '2015-02-21 20:18:27.000000', NULL, 1),
