(7319871, 1142101, 179675, '<td valign="top">Reminds me of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=62357" rel="nofollow" target="_blank">salmiakki</a>! Awesomely processed..very nice tonal range and motion. Quite beautiful,really.<br/><br/><i>Message edited by author 2015-03-01 13:16:36.</i></td>', 'Reminds me of  salmiakki! Awesomely processed..very nice tonal range and motion. Quite beautiful,really.', '2015-02-22 07:29:53.000000', '2015-03-01 13:16:36.000000', 0),
